        + `可用的是 ${DOMAINS.join('、')}`);
    }
    if (!Array.isArray(patterns) || patterns.length === 0) {
      throw new Error(`工具「${tool}」声明了写域「${domain}」却一个字段模式都没给——`
        + '写域必须写清允许写哪些字段（不许写「什么都能写」）');
