  return {
    PATH: [...venv, hostPath].join(path.delimiter),
    HOME: sandboxHome,
    TMPDIR: sandboxHome,
    TEMP: sandboxHome,
    TMP: sandboxHome,
    LANG: process.env.LANG ?? 'C.UTF-8',
    LC_ALL: process.env.LC_ALL ?? process.env.LANG ?? 'C.UTF-8',
